package plugin

import (
	"crypto/sha256"
	"encoding/hex"
	"strings"
)

// AdminModelPage is generated by the host from declared models and routes.
// It is not accepted as plugin-authored executable metadata.
type AdminModelPage struct {
	Name   string    `json:"name"`
	Schema ModelSpec `json:"schema"`
}

func adminModelReadOnly(action string) bool {
	return action == "read" || action == "list"
}

func adminModelPageID(name string) string {
	digest := sha256.Sum256([]byte(name))
	return "model-" + strings.ToLower(strings.ReplaceAll(name, "_", "-")) + "-" + hex.EncodeToString(digest[:4])
}

// AdminForOperator returns a derived view without mutating registered manifests.
// No new capabilities or routes are created. Explicit pages are retained.
func (m Manifest) AdminForOperator() *AdminSpec {
	result := &AdminSpec{Version: 1}
	seen := map[string]bool{}
	if m.Admin != nil && m.Admin.Version == 1 {
		for _, page := range m.Admin.Pages {
			result.Pages = append(result.Pages, page)
			seen[page.ID] = true
		}
	}
	for _, name := range sortedContractKeys(m.Models) {
		id := adminModelPageID(name)
		if seen[id] {
			continue
		}
		page := AdminPage{ID: id, Title: m.Title + ": " + name, Model: &AdminModelPage{Name: name, Schema: m.Models[name]}}
		for _, route := range m.Routes {
			if route.Helper != "host.model" || route.Model == nil || route.Model.Name != name {
				continue
			}
			kind := route.Model.Action
			action := AdminAction{Title: kind, Operation: route.Operation, ReadOnly: adminModelReadOnly(kind), ModelAction: kind, ModelTransition: route.Model.Transition}
			if kind == "list" {
				action.Fields = []AdminField{{Name: "after", Type: "string"}}
				action.Result = &AdminResultSpec{Type: "table"}
			} else {
				action.Fields = []AdminField{{Name: "id", Type: "string", Required: true}}
				if kind == "update" || kind == "delete" || kind == "transition" {
					action.Fields = append(action.Fields, AdminField{Name: "revision", Type: "string", Required: true})
				}
				if kind == "create" || kind == "update" {
					action.Fields = append(action.Fields, AdminField{Name: "fields", Type: "json", Required: true})
				}
				action.Result = &AdminResultSpec{Type: "detail"}
			}
			if kind == "transition" {
				action.Title = route.Model.Transition
			}
			page.Actions = append(page.Actions, action)
		}
		if len(page.Actions) > 0 {
			result.Pages = append(result.Pages, page)
		}
	}
	if len(result.Pages) == 0 {
		return nil
	}
	return result
}
